#include <iostream>\n#include <fstream>\n#include <vector>\n#include <string>\n\nclass Database {\npublic:\n    void saveMembers(const std::vector<std::string>& members) {\n        std::ofstream ofs("members.txt");\n        for (const auto& member : members) {\n            ofs << member << '\n';\n        }\n        ofs.close();\n    }\n\n    void loadMembers(std::vector<std::string>& members) {\n        std::ifstream ifs("members.txt");\n        std::string line;\n        while (std::getline(ifs, line)) {\n            members.push_back(line);\n        }\n        ifs.close();\n    }\n\n    void saveTrainers(const std::vector<std::string>& trainers) {\n        std::ofstream ofs("trainers.txt");\n        for (const auto& trainer : trainers) {\n            ofs << trainer << '\n';\n        }\n        ofs.close();\n    }\n\n    void loadTrainers(std::vector<std::string>& trainers) {\n        std::ifstream ifs("trainers.txt");\n        std::string line;\n        while (std::getline(ifs, line)) {\n            trainers.push_back(line);\n        }\n        ifs.close();\n    }\n\n    void saveWorkoutPlans(const std::vector<std::string>& workoutPlans) {\n        std::ofstream ofs("workout_plans.txt");\n        for (const auto& plan : workoutPlans) {\n            ofs << plan << '\n';\n        }\n        ofs.close();\n    }\n\n    void loadWorkoutPlans(std::vector<std::string>& workoutPlans) {\n        std::ifstream ifs("workout_plans.txt");\n        std::string line;\n        while (std::getline(ifs, line)) {\n            workoutPlans.push_back(line);\n        }\n        ifs.close();\n    }\n\n    void saveAttendance(const std::vector<std::string>& attendance) {\n        std::ofstream ofs("attendance.txt");\n        for (const auto& record : attendance) {\n            ofs << record << '\n';\n        }\n        ofs.close();\n    }\n\n    void loadAttendance(std::vector<std::string>& attendance) {\n        std::ifstream ifs("attendance.txt");\n        std::string line;\n        while (std::getline(ifs, line)) {\n            attendance.push_back(line);\n        }\n        ifs.close();\n    }\n\n    void savePayments(const std::vector<std::string>& payments) {\n        std::ofstream ofs("payments.txt");\n        for (const auto& payment : payments) {\n            ofs << payment << '\n';\n        }\n        ofs.close();\n    }\n\n    void loadPayments(std::vector<std::string>& payments) {\n        std::ifstream ifs("payments.txt");\n        std::string line;\n        while (std::getline(ifs, line)) {\n            payments.push_back(line);\n        }\n        ifs.close();\n    }\n};\n